      title=h4?h4.text().trim():""
    }
    if(!title){title="P"+(out.length+1)}
    out.push({n:title,u:u})
  }
  return out
}

function H1CONTENT(java,source,result,baseUrl){
  var d=org.jsoup.Jsoup.parse(String(result))
  var vp=d.selectFirst("video#player")
  if(!vp){return ""}
  var srcs=vp.select("source")
